1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, HTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	from urllib.parse import urlsplit
11	
12	PRODUCT = "OpenSurvey"
13	RESOURCE = "surveys"
14	MAX_BODY_BYTES = 10 * 1024 * 1024
15	QUESTION_TYPES = ("text", "single_choice")
16	
17	PAGE = r"""<!doctype html>
18	<html lang="zh-CN">
19	<meta charset="utf-8">
20	<meta name="viewport" content="width=device-width,initial-scale=1">
21	<title>OpenSurvey · 问卷调查与反馈管理</title>
22	<style>
23	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
24	*{box-sizing:border-box}
25	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
26	a{color:var(--blue)}
27	h1{margin-bottom:.2rem}
28	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
29	.muted{color:var(--grey);font-size:.92rem}
30	ul.plain{list-style:none;padding-left:0}
31	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
32	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
33	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
34	textarea{resize:vertical}
35	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
36	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
37	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
38	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
39	.q-index{font-weight:700}
40	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
41	.tag.required{background:#fdecea;color:var(--red)}
42	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
43	.spacer{flex:1}
44	button{font:inherit;cursor:pointer}
45	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
46	.btn.secondary{background:#fff;color:var(--blue)}
47	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
48	.link.danger{color:var(--red)}
49	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
50	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
51	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
52	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
53	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
54	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
55	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
56	.invalid{border-color:var(--red)!important;background:#fdf6f5}
57	.detail-meta{color:var(--grey);font-size:.9rem}
58	.detail-desc,.opt-text-display{white-space:pre-wrap}
59	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
60	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
61	.q-list>li{margin:1rem 0}
62	.q-list .q-line{font-weight:600}
63	.q-list ol{margin:.4rem 0 0 1.4rem}
64	</style>
65	<main>
66	<h1>OpenSurvey</h1>
67	<p>问卷调查与反馈管理</p>
68	<div id="app"></div>
69	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
70	</main>
71	<script>
72	"use strict";
73	const app = document.getElementById("app");
74	
75	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
76	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
77	// 返回也必须丢弃，不能覆盖用户当前所在页面。
78	let activeView = 0;
79	
80	function h(tag, attrs, ...children) {
81	  const el = document.createElement(tag);
82	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
83	    if (v === null || v === undefined) continue;
84	    if (k === "class") el.className = v;
85	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
86	    else el.setAttribute(k, v);
87	  }
88	  for (const child of children.flat()) {
89	    if (child === null || child === undefined) continue;
90	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
91	  }
92	  return el;
93	}
94	
95	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
96	
97	function buildSurveyForm(existing, hooks, view) {
98	  const mode = existing ? "edit" : "create";
99	
100	  const banner = h("div", {class: "banner", id: "form-banner"});
101	  banner.hidden = true;
102	
103	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
104	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
105	  const titleErr = h("p", {class: "field-err", id: "title-err"});
106	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
107	  const qBox = h("div", {id: "questions"});
108	  const qErr = h("p", {class: "field-err", id: "questions-err"});
109	
110	  function renumber() {
111	    const cards = qBox.querySelectorAll(".q-card");
112	    cards.forEach((card, i) => {
113	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
114	      card.querySelectorAll(".opt-row").forEach((row, j) => {
115	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
116	      });
117	    });
118	  }
119	
120	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
121	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
122	  function autoGrow(el) {
123	    el.style.height = "auto";
124	    el.style.height = `${el.scrollHeight}px`;
125	  }
126	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
127	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
128	
129	  function optionRow(value) {
130	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
131	    text.addEventListener("input", () => autoGrow(text));
132	    if (value !== undefined && value !== null) { text.value = value; scheduleGrow(text); }
133	    const row = h("div", {class: "opt-row"},
134	      h("span", {class: "opt-index"}, "选项"),
135	      text,
136	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
137	    );
138	    return row;
139	  }
140	
141	  function addQuestion(type, prefill) {
142	    const isChoice = type === "single_choice";
143	    const options = h("div", {class: "options"});
144	    const card = h("div", {class: "card q-card", "data-type": type},
145	      h("div", {class: "q-head"},
146	        h("span", {class: "q-index"}, "第 N 题"),
147	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
148	        h("label", {class: "req"},
149	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
150	        h("span", {class: "spacer"}),
151	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
152	      ),
153	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
154	      h("p", {class: "field-err q-title-err"})
155	    );
156	    if (isChoice) {
157	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
158	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
159	      else options.append(optionRow(), optionRow());
160	      card.append(
161	        options,
162	        h("p", {class: "field-err opt-err"}),
163	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
164	      );
165	      card.querySelector(".add-opt").addEventListener("click", () => {
166	        options.append(optionRow());
167	        renumber();
168	        options.querySelector(".opt-row:last-child .opt-text").focus();
169	      });
170	    }
171	    const qTitleEl = card.querySelector(".q-title");
172	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
173	    if (prefill) {
174	      qTitleEl.value = prefill.title != null ? prefill.title : "";
175	      card.querySelector(".q-required").checked = !!prefill.required;
176	    }
177	    scheduleGrow(qTitleEl);
178	    qBox.append(card);
179	    renumber();
180	    if (!prefill) qTitleEl.focus();
181	    return card;
182	  }
183	
184	  function clearErrors() {
185	    banner.hidden = true;
186	    banner.replaceChildren();
187	    titleErr.textContent = "";
188	    qErr.textContent = "";
189	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
190	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
191	  }
192	
193	  function showBanner(items) {
194	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
195	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
196	    banner.hidden = false;
197	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
198	  }
199	
200	  const actionButtons = [
201	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
202	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
203	    h("span", {class: "spacer"})
204	  ];
205	  if (mode === "edit") {
206	    // 离开编辑页即丢弃全部未保存的增删与输入
207	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
208	  }
209	  actionButtons.push(h("button", {type: "submit", class: "btn"},
210	    mode === "edit" ? "保存修改" : "保存整份问卷"));
211	
212	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
213	    banner,
214	    h("section", null,
215	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
216	      mode === "edit"
217	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
218	        : null,
219	      h("label", {for: "survey-title"}, "标题"),
220	      titleInput, titleErr,
221	      h("label", {for: "survey-desc"}, "说明"),
222	      descArea,
223	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
224	      qBox, qErr,
225	      h("div", {class: "row-actions"}, actionButtons)
226	    )
227	  );
228	
229	  titleInput.addEventListener("input", () => autoGrow(titleInput));
230	  if (mode === "edit") {
231	    titleInput.value = existing.title != null ? existing.title : "";
232	    descArea.value = existing.description || "";
233	    existing.questions.forEach(question => addQuestion(question.type, question));
234	    renumber();
235	    scheduleGrow(titleInput);
236	  }
237	
238	  async function submitForm(event) {
239	    event.preventDefault();
240	    clearErrors();
241	    const problems = [];
242	
243	    const title = titleInput.value.trim();
244	    if (!title) {
245	      titleInput.classList.add("invalid");
246	      titleErr.textContent = "标题不能为空。";
247	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
248	    }
249	
250	    const cards = [...qBox.querySelectorAll(".q-card")];
251	    if (cards.length === 0) {
252	      qErr.textContent = "问卷至少需要保留一道题。";
253	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
254	    }
255	
256	    const payloadQuestions = [];
257	    cards.forEach((card, i) => {
258	      const loc = `第 ${i + 1} 题`;
259	      const titleEl = card.querySelector(".q-title");
260	      const qTitle = titleEl.value.trim();
261	      if (!qTitle) {
262	        titleEl.classList.add("invalid");
263	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
264	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
265	      }
266	      const q = {
267	        type: card.dataset.type,
268	        title: qTitle,
269	        required: card.querySelector(".q-required").checked
270	      };
271	      if (card.dataset.type === "single_choice") {
272	        const optInputs = [...card.querySelectorAll(".opt-text")];
273	        const values = optInputs.map(el => el.value.trim());
274	        const optErr = card.querySelector(".opt-err");
275	        const seen = new Set();
276	        values.forEach((val, j) => {
277	          if (!val) {
278	            optInputs[j].classList.add("invalid");
279	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
280	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
281	          } else if (seen.has(val)) {
282	            optInputs[j].classList.add("invalid");
283	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
284	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
285	          }
286	          seen.add(val);
287	        });
288	        if (values.length < 2) {
289	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
290	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
291	        }
292	        q.options = values;
293	      }
294	      payloadQuestions.push(q);
295	    });
296	
297	    if (problems.length) {
298	      showBanner(problems);
299	      return;
300	    }
301	
302	    const payload = {title, description: descArea.value, questions: payloadQuestions};
303	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
304	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
305	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
306	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
307	    const submitView = view;
308	    let resp;
309	    try {
310	      resp = await fetch(endpoint, {
311	        method: mode === "edit" ? "PUT" : "POST",
312	        headers: {"Content-Type": "application/json"},
313	        body: JSON.stringify(payload)
314	      });
315	    } catch (err) {
316	      if (submitView !== activeView) return;
317	      // 请求未成功：保留当前全部输入与增删结果
318	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
319	      return;
320	    }
321	    if (submitView !== activeView) return;
322	    let data = {};
323	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
324	    if (submitView !== activeView) return;
325	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
326	    if (saved && data.id !== undefined) {
327	      if (mode === "create") {
328	        form.reset();
329	        qBox.replaceChildren();
330	        autoGrow(titleInput);
331	        if (hooks && hooks.onCreated) hooks.onCreated();
332	      }
333	      location.hash = `#/surveys/${data.id}`;
334	      return;
335	    }
336	    // 服务端未确认保存成功：不清空任何输入，展示具体问题
337	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
338	  }
339	
340	  return form;
341	}
342	
343	/* ---------- 首页 ---------- */
344	
345	function renderHome() {
346	  const view = ++activeView;
347	  app.replaceChildren();
348	
349	  const listSection = h("section", null,
350	    h("h2", null, "问卷列表"),
351	    h("ul", {class: "plain", id: "survey-list"}, h("li", {class: "muted"}, "加载中…"))
352	  );
353	  const listEl = listSection.querySelector("#survey-list");
354	
355	  async function loadSurveys() {
356	    let data;
357	    try {
358	      const resp = await fetch("/api/surveys");
359	      data = await resp.json();
360	    } catch (err) {
361	      if (view !== activeView) return;
362	      listEl.replaceChildren(h("li", {class: "muted"}, "问卷列表加载失败。"));
363	      return;
364	    }
365	    if (view !== activeView) return;
366	    listEl.replaceChildren();
367	    if (!data.surveys.length) {
368	      listEl.append(h("li", {class: "muted"}, "还没有问卷记录。"));
369	      return;
370	    }
371	    for (const survey of data.surveys) {
372	      listEl.append(h("li", null,
373	        h("a", {href: `#/surveys/${survey.id}`}, `#${survey.id} ${survey.title}`)));
374	    }
375	  }
376	
377	  app.append(
378	    listSection,
379	    buildSurveyForm(null, {onCreated: loadSurveys}, view)
380	  );
381	  loadSurveys();
382	}
383	
384	/* ---------- 问卷详情 ---------- */
385	
386	async function renderDetail(id) {
387	  const view = ++activeView;
388	  app.replaceChildren(
389	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
390	    h("p", {class: "muted", id: "detail-status"}, "加载中…")
391	  );
392	  const status = document.getElementById("detail-status");
393	
394	  let survey;
395	  try {
396	    const resp = await fetch(`/api/surveys/${id}`);
397	    if (view !== activeView) return;
398	    if (resp.status === 404) {
399	      status.textContent = `问卷 #${id} 不存在。`;
400	      return;
401	    }
402	    if (!resp.ok) {
403	      status.textContent = `详情加载失败（HTTP ${resp.status}），请稍后重试。`;
404	      return;
405	    }
406	    survey = await resp.json();
407	  } catch (err) {
408	    if (view !== activeView) return;
409	    status.textContent = `详情加载失败：${err}`;
410	    return;
411	  }
412	  if (view !== activeView) return;
413	
414	  app.replaceChildren(
415	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
416	    h("h2", null, `#${survey.id} ${survey.title}`),
417	    h("div", {class: "row-actions"},
418	      h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿"),
419	      h("a", {class: "btn secondary", href: "#/"}, "返回首页")
420	    ),
421	    h("h3", null, "说明"),
422	    survey.description
423	      ? h("p", {class: "detail-desc"}, survey.description)
424	      : h("p", {class: "muted"}, "（无说明）"),
425	    h("h3", null, `题目（共 ${survey.questions.length} 道）`)
426	  );
427	  if (!survey.questions.length) {
428	    app.append(
429	      h("p", {class: "muted"}, "该问卷草稿还没有题目，可进入编辑补齐。"),
430	      h("p", null, h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿并添加题目"))
431	    );
432	    return;
433	  }
434	  app.append(h("ol", {class: "q-list"},
435	    survey.questions.map((q, i) => h("li", null,
436	      h("div", {class: "q-line"},
437	        `${i + 1}. ${q.title} `,
438	        h("span", {class: "tag"}, q.type === "single_choice" ? "单选题" : "文本题"),
439	        " ",
440	        h("span", {class: "tag" + (q.required ? " required" : "")}, q.required ? "必填" : "选填")
441	      ),
442	      q.options && q.options.length
443	        ? h("ol", {start: "1"}, q.options.map(opt => h("li", {class: "opt-text-display"}, opt)))
444	        : null
445	    )))
446	  );
447	}
448	
449	/* ---------- 编辑草稿 ---------- */
450	
451	function showEditLoadError(id, message, view) {
452	  // 加载失败时明确提示，绝不能用空白编辑表单覆盖已有内容
453	  if (view !== activeView) return;
454	  app.replaceChildren(
455	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
456	    h("h2", null, `编辑问卷草稿 #${id}`),
457	    h("div", {class: "banner", role: "alert"},
458	      h("strong", null, "问卷内容加载失败，未打开编辑表单："),
459	      h("p", {class: "detail-meta", style: "margin:.4rem 0 0"}, message),
460	      h("p", {style: "margin:.6rem 0 0"},
461	        h("button", {type: "button", class: "btn secondary", onclick: () => renderEdit(id)}, "重试"), " ",
462	        h("a", {class: "btn secondary", href: `#/surveys/${id}`}, "返回详情"))
463	    )
464	  );
465	}
466	
467	async function renderEdit(id) {
468	  const view = ++activeView;
469	  app.replaceChildren(
470	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
471	    h("p", {class: "muted", id: "edit-status"}, "加载中…")
472	  );
473	
474	  let survey;
475	  try {
476	    const resp = await fetch(`/api/surveys/${id}`);
477	    if (view !== activeView) return;
478	    if (resp.status === 404) {
479	      showEditLoadError(id, `问卷 #${id} 不存在。`, view);
480	      return;
481	    }
482	    if (!resp.ok) {
483	      showEditLoadError(id, `服务端返回异常（HTTP ${resp.status}），请稍后重试。`, view);
484	      return;
485	    }
486	    survey = await resp.json();
487	  } catch (err) {
488	    showEditLoadError(id, `网络错误：${err}。已保存的问卷内容未受影响，可重试加载。`, view);
489	    return;
490	  }
491	
492	  if (view !== activeView) return;
493	  app.replaceChildren(
494	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
495	    buildSurveyForm(survey, {}, view)
496	  );
497	}
498	
499	function route() {
500	  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
501	  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
502	  if (editMatch) renderEdit(Number(editMatch[1]));
503	  else if (detailMatch) renderDetail(Number(detailMatch[1]));
504	  else renderHome();
505	}
506	window.addEventListener("hashchange", route);
507	route();
508	</script>
509	</html>
510	"""
511	
512	
513	def validate_survey(obj):
514	    """Validate a decoded survey payload.
515	
516	    Returns (clean_survey, None) on success or (None, error_message) on failure.
517	    Strings are stored trimmed of surrounding whitespace; description keeps its
518	    raw value so Chinese, quotes and newlines are preserved.
519	    """
520	    if not isinstance(obj, dict):
521	        return None, "请求体必须是 JSON 对象"
522	    if "title" not in obj:
523	        return None, "缺少字段 title"
524	    title = obj["title"]
525	    if not isinstance(title, str):
526	        return None, "title 必须是字符串"
527	    title = title.strip()
528	    if not title:
529	        return None, "title 不能为空（或全为空白字符）"
530	
531	    description = obj.get("description", "")
532	    if not isinstance(description, str):
533	        return None, "description 必须是字符串"
534	
535	    if "questions" not in obj:
536	        return None, "缺少字段 questions"
537	    raw_questions = obj["questions"]
538	    if not isinstance(raw_questions, list):
539	        return None, "questions 必须是数组"
540	    if len(raw_questions) == 0:
541	        return None, "questions 至少需要一道题"
542	
543	    questions = []
544	    for index, raw_question in enumerate(raw_questions, start=1):
545	        location = f"第 {index} 题"
546	        if not isinstance(raw_question, dict):
547	            return None, f"{location}（questions[{index - 1}]）必须是对象"
548	
549	        if "type" not in raw_question:
550	            return None, f"{location}：缺少字段 type"
551	        question_type = raw_question["type"]
552	        if not isinstance(question_type, str):
553	            return None, f"{location}：type 必须是字符串"
554	        if question_type not in QUESTION_TYPES:
555	            shown = json.dumps(question_type, ensure_ascii=False)
556	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
557	
558	        if "title" not in raw_question:
559	            return None, f"{location}：缺少字段 title"
560	        question_title = raw_question["title"]
561	        if not isinstance(question_title, str):
562	            return None, f"{location}：title 必须是字符串"
563	        question_title = question_title.strip()
564	        if not question_title:
565	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
566	
567	        required = raw_question.get("required", False)
568	        if not isinstance(required, bool):
569	            return None, f"{location}：required 必须是布尔值"
570	
571	        raw_options = raw_question.get("options", [])
572	        if not isinstance(raw_options, list):
573	            return None, f"{location}：options 必须是数组"
574	
575	        options = []
576	        if question_type == "text":
577	            if len(raw_options) > 0:
578	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
579	        else:
580	            if len(raw_options) < 2:
581	                return None, f"{location}：单选题至少需要两个选项"
582	            seen = set()
583	            for option_index, raw_option in enumerate(raw_options, start=1):
584	                if not isinstance(raw_option, str):
585	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
586	                option = raw_option.strip()
587	                if not option:
588	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
589	                if option in seen:
590	                    shown = json.dumps(option, ensure_ascii=False)
591	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
592	                seen.add(option)
593	                options.append(option)
594	
595	        questions.append({
596	            "type": question_type,
597	            "title": question_title,
598	            "required": required,
599	            "options": options,
600	        })
601	
602	    return {
603	        "title": title,
604	        "description": description,
605	        "questions": questions,
606	    }, None
607	
608	
609	def main():
610	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
611	    commands = parser.add_subparsers(dest="command", required=True)
612	    serve = commands.add_parser("serve", help="Start the HTTP service")
613	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
614	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
615	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
616	    args = parser.parse_args()
617	    if not 0 <= args.port <= 65535:
618	        parser.error("port must be between 0 and 65535")
619	    args.data_dir.mkdir(parents=True, exist_ok=True)
620	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite")
621	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
622	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
623	    if "description" not in columns:
624	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
625	    database.execute(
626	        "CREATE TABLE IF NOT EXISTS questions ("
627	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
628	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
629	    )
630	    database.execute(
631	        "CREATE TABLE IF NOT EXISTS question_options ("
632	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
633	    )
634	    database.commit()
635	
636	    def survey_detail(survey_id):
637	        row = database.execute(
638	            "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
639	            (survey_id,),
640	        ).fetchone()
641	        if row is None:
642	            return None
643	        title, description = row
644	        questions = []
645	        question_rows = database.execute(
646	            "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
647	            (survey_id,),
648	        ).fetchall()
649	        for question_id, question_type, question_title, required in question_rows:
650	            options = [option_row[0] for option_row in database.execute(
651	                "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
652	                (question_id,),
653	            )]
654	            questions.append({
655	                "type": question_type,
656	                "title": question_title,
657	                "required": bool(required),
658	                "options": options,
659	            })
660	        return {
661	            "id": survey_id,
662	            "title": title,
663	            "description": description,
664	            "questions": questions,
665	        }
666	
667	    def save_survey(clean):
668	        """Insert the whole survey atomically; returns the new id."""
669	        try:
670	            cursor = database.execute(
671	                "INSERT INTO surveys (title, description) VALUES (?, ?)",
672	                (clean["title"], clean["description"]),
673	            )
674	            survey_id = cursor.lastrowid
675	            write_questions(survey_id, clean["questions"])
676	            database.commit()
677	            return survey_id
678	        except Exception:
679	            database.rollback()
680	            raise
681	
682	    def write_questions(survey_id, questions):
683	        """Replace all questions/options of a survey with the given ordered list."""
684	        old_question_ids = [row[0] for row in database.execute(
685	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
686	        )]
687	        if old_question_ids:
688	            placeholders = ",".join("?" for _ in old_question_ids)
689	            database.execute(
690	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
691	                old_question_ids,
692	            )
693	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
694	        for position, question in enumerate(questions):
695	            question_cursor = database.execute(
696	                "INSERT INTO questions (survey_id, position, type, title, required) "
697	                "VALUES (?, ?, ?, ?, ?)",
698	                (survey_id, position, question["type"], question["title"],
699	                 1 if question["required"] else 0),
700	            )
701	            question_id = question_cursor.lastrowid
702	            for option_position, option in enumerate(question["options"]):
703	                database.execute(
704	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
705	                    (question_id, option_position, option),
706	                )
707	
708	    def replace_survey(survey_id, clean):
709	        """Replace a whole survey atomically; keeps the same id.
710	
711	        Returns False when the survey does not exist (no record is created).
712	        """
713	        row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
714	        if row is None:
715	            return False
716	        try:
717	            database.execute(
718	                "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
719	                (clean["title"], clean["description"], survey_id),
720	            )
721	            write_questions(survey_id, clean["questions"])
722	            database.commit()
723	            return True
724	        except Exception:
725	            database.rollback()
726	            raise
727	
728	    class Handler(BaseHTTPRequestHandler):
729	        def respond(self, status, value, *, html=False, allow=None):
730	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
731	            self.send_response(status)
732	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
733	            self.send_header("Content-Length", str(len(payload)))
734	            if status == 405 and allow is not None:
735	                self.send_header("Allow", ", ".join(allow))
736	            self.end_headers()
737	            self.wfile.write(payload)
738	
739	        def list_surveys(self):
740	            records = [
741	                {"id": row[0], "title": row[1]}
742	                for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
743	            ]
744	            self.respond(200, {RESOURCE: records})
745	
746	        def read_payload(self):
747	            """Read and decode a JSON request body.
748	
749	            Returns (payload, None) or (None, error_message).
750	            """
751	            try:
752	                length = int(self.headers.get("Content-Length") or 0)
753	            except ValueError:
754	                length = -1
755	            if length < 0:
756	                return None, "Content-Length 无效"
757	            if length > MAX_BODY_BYTES:
758	                return None, "请求体过大"
759	            body = self.rfile.read(length) if length else b""
760	            try:
761	                return json.loads(body.decode("utf8")), None
762	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
763	                return None, f"请求体不是合法 JSON：{error}"
764	
765	        def create_survey(self):
766	            payload, error = self.read_payload()
767	            if error is not None:
768	                self.respond(400, {"error": error})
769	                return
770	
771	            clean, error = validate_survey(payload)
772	            if error is not None:
773	                self.respond(400, {"error": error})
774	                return
775	            try:
776	                survey_id = save_survey(clean)
777	            except sqlite3.DatabaseError as error:
778	                self.respond(500, {"error": f"保存失败：{error}"})
779	                return
780	            result = {"id": survey_id, **clean}
781	            self.respond(201, result)
782	
783	        def update_survey(self, survey_id):
784	            payload, read_error = self.read_payload()
785	            if survey_detail(survey_id) is None:
786	                # Editing a missing id is always 404 and must never create one.
787	                self.respond(404, {"error": "not found"})
788	                return
789	            if read_error is not None:
790	                self.respond(400, {"error": read_error})
791	                return
792	
793	            # Full replacement: validate before touching the stored draft so a
794	            # rejected request leaves the old survey exactly as it was.
795	            clean, error = validate_survey(payload)
796	            if error is not None:
797	                self.respond(400, {"error": error})
798	                return
799	            try:
800	                replace_survey(survey_id, clean)
801	            except sqlite3.DatabaseError as error:
802	                self.respond(500, {"error": f"保存失败：{error}"})
803	                return
804	            self.respond(200, {"id": survey_id, **clean})
805	
806	        def route(self):
807	            location = urlsplit(self.path).path
808	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
809	
810	            if location == "/api/surveys":
811	                allowed = ["GET", "POST"]
812	            elif location in ("/", "/health"):
813	                allowed = ["GET"]
814	            elif detail_match:
815	                allowed = ["GET", "PUT"]
816	            else:
817	                self.respond(404, {"error": "not found"})
818	                return
819	
820	            if self.command not in allowed:
821	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
822	                return
823	
824	            if location == "/":
825	                self.respond(200, PAGE, html=True)
826	            elif location == "/health":
827	                self.respond(200, {"status": "ok", "product": PRODUCT})
828	            elif location == "/api/surveys":
829	                if self.command == "POST":
830	                    self.create_survey()
831	                else:
832	                    self.list_surveys()
833	            else:
834	                survey_id = int(detail_match.group(1))
835	                if self.command == "PUT":
836	                    self.update_survey(survey_id)
837	                    return
838	                detail = survey_detail(survey_id)
839	                if detail is None:
840	                    self.respond(404, {"error": "not found"})
841	                else:
842	                    self.respond(200, detail)
843	
844	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
845	
846	    def stop(_signal, _frame):
847	        raise KeyboardInterrupt
848	
849	    signal.signal(signal.SIGTERM, stop)
850	    server = None
851	    try:
852	        server = HTTPServer((args.host, args.port), Handler)
853	        host, port = server.server_address[:2]
854	        address = f"[{host}]" if ":" in host else host
855	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
856	        server.serve_forever()
857	    except KeyboardInterrupt:
858	        pass
859	    finally:
860	        if server is not None:
861	            server.server_close()
862	        database.close()
863	
864	
865	if __name__ == "__main__":
866	    main()
